entries[184615] = { ["name"] = "Extradimensional Pockets", ["text"] = "Permanent Upgrade: Torghast\nBinds when picked up\nUnique\nUse: Gain extra storage space while in Torghast, allowing Obleron Armaments to be found in higher amounts.\nRequires that Ve'nari has an Apprehensive or higher opinion of you.\n\"These pockets are substantially larger on the inside than they appear.\"" }
entries[184617] = { ["name"] = "Bangle of Seniority", ["text"] = "Permanent Upgrade: Torghast\nBinds when picked up\nUnique\nUse: While in Torghast, Broker vendors will have a chance to offer you Uncommon options.\nRequires that Ve'nari has a Tentative or higher opinion of you.\n\"This bangle once indicated Ve'nari's status in the Ve cartel. Now, it belongs to you.\"" }
entries[184618] = { ["name"] = "Rank Insignia: Acquisitionist", ["text"] = "Permanent Upgrade: Torghast\nBinds when picked up\nUnique\nUse: While in Torghast, Broker vendors will have a chance to offer you one Rare option.\nRequires that Ve'nari has a Cordial or higher opinion of you.\n\"This certifies you as a deputy of the Ve cartel. Which you are absolutely not, but they won't know that.\"" }
entries[184619] = { ["name"] = "Loupe of Unusual Charm", ["text"] = "Permanent Upgrade: Torghast\nBinds when picked up\nUnique\nUse: While in Torghast, a Broker vendor may offer you discounted Anima Hoards.\nRequires that Ve'nari has a Cordial or higher opinion of you.\n\"Ve'nari has imbued this jeweler's loupe with a compulsion spell, making some brokers inclined to offer you special deals.\"" }
entries[184620] = { ["name"] = "Vessel of Unfortunate Spirits", ["text"] = "Permanent Upgrade: Torghast\nBinds when picked up\nUnique\nUse: While in Torghast, your first death does not count against you.\nRequires that Ve'nari has an Apprehensive or higher opinion of you.\n\"Dangerous magic ties the fate of any who hold this vessel with that of the spirit contained therein.\"" }
entries[184621] = { ["name"] = "Ritual Prism of Fortune", ["text"] = "Permanent Upgrade: Torghast\nBinds when picked up\nUnique\nUse: While in Torghast, your chance of receiving Epic Anima Powers is permanently increased.\nRequires that Ve'nari has an Ambivalent or higher opinion of you.\n\"Ve'nari has inscribed this crystal with glyphs which are said to ward against the whims of fate.\"" }
