entries[184624] = { ["name"] = "Extra Sugary Fish Feast", ["text"] = "Use: Set out a great feast that will feed your party!\n\nRestores 173077 health 138461 and mana over 20 sec. If you spend at least 10 seconds eating you will become Well Fed, increasing Versatility for 20 min.\nSell Price:" }
entries[184625] = { ["name"] = "Recipe: Extra Sugary Fish Feast", ["text"] = "Binds when picked up\nUse: Teaches you how to cook an Extra Sugary Fish Feast.\nRequires Classic Cooking (150)\nSell Price:\nExtra Sugary Fish Feast\nUse: Set out a great feast that will feed your party!\n\nRestores 173077 health 138461 and mana over 20 sec. If you spend at least 10 seconds eating you will become Well Fed, increasing Versatility for 20 min.\nSell Price:\nRequires Darkmoon Daggermaw (5)" }
