entries[184649] = { ["name"] = "Mawrat Cannon", ["text"] = "Binds when picked up\nUnique\nUse: Launch an exploding Mawrat at your target, dealing (Total Health / 10) Shadowflame damage to all enemies within 8 yd and killing the Mawrat. Can only be used in Torghast. (5 Min Cooldown)\n\"An extremely large-barreled weapon purpose-built to launch the rats which call Torghast home into other creatures at high speeds.\"\nSell Price:" }
entries[184650] = { ["name"] = "Adventure Campaign Progress", ["text"] = "\"This challenge leads to additional adventures with greater rewards.\"" }
entries[184651] = { ["name"] = "Maw-Touched Miasma", ["text"] = "Binds when picked up\nUse: Surround yourself in sickly miasma, dealing (Total Health / 5) damage to any Mawrats within 15 yds every 1 sec for 30 min. Can only be used in Torghast. (5 Min Cooldown)\nRequires that Ve'nari has a Tentative or higher opinion of you.\n\"A sickening vial of gas, this substance is especially potent against the omnipresent Mawrats.\"\nSell Price:" }
entries[184652] = { ["name"] = "Phantasmic Infuser", ["text"] = "Binds when picked up\nUnique\nUse: Consume 100 Phantasma, using the energy created by the substance to empower yourself for 30 min. Can only be used in Torghast. (15 Min Cooldown)\nRequires that Ve'nari has an Ambivalent or higher opinion of you.\n\"This device is said to consume Phantasma to fuel you with great power for a limited time. The device is reusable, but the Phantasma is destroyed in the process.\"\nSell Price:" }
entries[184653] = { ["name"] = "Animated Levitating Chain", ["text"] = "Permanent Upgrade: The Maw\nBinds when picked up\nUnique\nUse: Bind the segment of chain to your own will, allowing you to direct it to some nearby locations.\nRequires that Ve'nari has a Tentative or higher opinion of you.\n\"This segment of magical chain was recovered from a helpless prisoner of the Jailer, lost to the Maw. It still retains a semblance of power.\"" }
